package com.creditsense.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="audit_logs") public class AuditLog { @Id private UUID id=UUID.randomUUID(); @ManyToOne @JoinColumn(name="actor_id") private User actor; private String action; @Column(name="entity_type") private String entityType; @Column(name="entity_id") private UUID entityId; @Column(name="before_state",columnDefinition="jsonb") @org.hibernate.annotations.JdbcTypeCode(org.hibernate.type.SqlTypes.JSON) private String beforeState; @Column(name="after_state",columnDefinition="jsonb") @org.hibernate.annotations.JdbcTypeCode(org.hibernate.type.SqlTypes.JSON) private String afterState; @Column(name="created_at") private Instant createdAt=Instant.now(); public AuditLog(){} public UUID getId(){return id;} public User getActor(){return actor;} public String getAction(){return action;} public String getEntityType(){return entityType;} public UUID getEntityId(){return entityId;} public String getBeforeState(){return beforeState;} public String getAfterState(){return afterState;} public Instant getCreatedAt(){return createdAt;} public void setActor(User v){actor=v;} public void setAction(String v){action=v;} public void setEntityType(String v){entityType=v;} public void setEntityId(UUID v){entityId=v;} public void setBeforeState(String v){beforeState=v;} public void setAfterState(String v){afterState=v;} }
